// "Little Pianist" (claude.ai artifact R6JdkhrcSf7EQ93gkd8GvH), Mom's player: animated sheet music + keyboard with
// a synthesised piano take (Jingle Bells). The code below is the artifact's script, unchanged except that it is wrapped in a
// mount function: element lookups go through `root` (ids prefixed lp-), and the loops stop on destroy().
/* eslint-disable */
// @ts-nocheck
export function mountLittlePianist(root) {
  let alive = true;

// ---------- song: Jingle Bells chorus (J. Pierpont, 1857, public domain), beginner C-position arrangement, twice ----------
const A_ = [
 [['E4',1,3],['E4',1],['E4',2]],
 [['E4',1],['E4',1],['E4',2]],
 [['E4',1],['G4',1,5],['C4',1.5,1],['D4',.5,2]],
 [['E4',4,3]],
 [['F4',1,4],['F4',1],['F4',1.5],['F4',.5]],
 [['F4',1],['E4',1],['E4',1],['E4',.5],['E4',.5]],
];
const RH_MEAS = [
 ...A_,
 [['E4',1],['D4',1,2],['D4',1],['E4',1]],
 [['D4',2],['G4',2,5]],
 ...A_,
 [['G4',1,5],['G4',1],['F4',1],['D4',1]],
 [['C4',4,1]],
];
const C=['C3','G3'], G=['D3','G3'], F=['F3','A3'];
const LH_MEAS=[[[C,4]],[[C,4]],[[C,4]],[[C,4]],[[F,4]],[[C,4]],[[G,4]],[[G,4]],
               [[C,4]],[[C,4]],[[C,4]],[[C,4]],[[F,4]],[[C,4]],[[G,4]],[[C,4]]];
const LH_FING={C3:5,G3:1,D3:4,F3:5,A3:2};

const NAMES={C:0,D:2,E:4,F:5,G:7,A:9,B:11}, DIA={C:0,D:1,E:2,F:3,G:4,A:5,B:6};
const midi=n=>12*(+n[1]+1)+NAMES[n[0]];
const dia=n=>7*(+n[1])+DIA[n[0]];

// flatten
const rh=[], lh=[], bars=[];
let b=0;
RH_MEAS.forEach((m,i)=>{bars.push(b); let bb=b;
  m.forEach(([p,d,f,slip])=>{rh.push({p,d,b:bb,f,slip,m:i});bb+=d});
  let lb=b; LH_MEAS[i].forEach(([ch,d])=>{lh.push({ps:ch,d,b:lb,m:i});lb+=d});
  b+=4;});
const TOTAL=b; bars.push(TOTAL);
// eighth-note beaming: pair consecutive eighths on the same beat
rh.forEach((n,i)=>{ if(n.d===.5){ const nx=rh[i+1]; if(nx&&nx.d===.5&&Math.floor(nx.b)===Math.floor(n.b)&&n.b%1===0){n.beamTo=nx;nx.beamed=true;} }});
rh.forEach(n=>{ if(n.d===.5&&!n.beamTo&&!n.beamed) n.flag=true; });

// ---------- a 7-year-old's performance ----------
let rand;
function seeded(s){return()=>{s|=0;s=s+0x6D2B79F5|0;let t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
let perf;
function makePerformance(seed){
  rand=seeded(seed); const r=(a,b)=>a+(b-a)*rand();
  const beat=60/r(108,114);
  let clock=1.6, drift=1, events=[], map=[{b:-3,t:clock-3*beat}];
  const wrongMeasure = -1; // this take is clean (no slip)
  rh.forEach((n,i)=>{
    // hesitations: new section, the hand jump down to G, and after the slip
    if(n.b===32) clock+=r(.25,.45);
    if(n.p==='G3') clock+=r(.18,.32);
    if(n.b===48) clock+=r(.05,.18);
    if(n.d===.5 && rand()<.6) clock+=r(.02,.06); // careful on the quick notes
    drift=Math.min(1.08,Math.max(.94,drift+r(-.025,.025)));
    const jit=r(-.035,.035);
    let on=clock+jit;
    // the slip: brushes the wrong key, notices, fixes it
    const slipNote = n.slip && n.m===wrongMeasure-0 ? n.slip : (n.m===wrongMeasure && n.d===.5 && n.p==='F4' ? 'G4':null);
    if(slipNote){ events.push({type:'rh',p:slipNote,on,off:on+r(.1,.14),vel:r(.35,.5),wrong:true}); on+=r(.16,.22); clock+=r(.16,.22); }
    n.t=on; map.push({b:n.b,t:on});
    let len=n.d*beat*drift;
    const phraseEnd = (n.b+n.d)%16===0 && n.b+n.d<TOTAL;
    if(phraseEnd) len*=r(1.08,1.2);
    if(n.d===.5) len*=r(.85,.95); // eighths come out a little quick
    clock+=len;
    const accent = n.b%4===0 ? .12:0;
    events.push({type:'rh',p:n.p,on,vel:Math.min(1,r(.55,.78)+accent),note:n});
  });
  // last note rings a bit longer, then hands come off
  const endT=clock+beat*1.2;
  map.push({b:TOTAL,t:clock});
  // releases: slightly detached, half notes not always held full value
  const rhEv=events.filter(e=>e.type==='rh'&&!e.wrong);
  rhEv.forEach((e,i)=>{const nx=rhEv[i+1];
    if(nx) e.off = nx.on - r(.03,.09) - (e.note.d>=2? r(0,.25):0);
    else e.off=endT; });
  // left hand: lands a touch late, lifts a little early
  const bt=x=>beatToTime(map,x);
  lh.forEach((c,i)=>{const on=bt(c.b)+r(.015,.07); const off=(i===lh.length-1)?endT+.1:bt(c.b+c.d)-r(.04,.12);
    c.ps.forEach((p,k)=>events.push({type:'lh',p,on:on+k*r(0,.018),off,vel:r(.32,.42),chord:c}));
    c.t=on;});
  events.sort((a,b)=>a.on-b.on);
  return {events,map,end:endT+1.2,beat};
}
function beatToTime(map,x){ for(let i=1;i<map.length;i++){const a=map[i-1],c=map[i]; if(x<=c.b) return a.t+(x-a.b)/(c.b-a.b)*(c.t-a.t);} const l=map[map.length-1]; return l.t+(x-l.b)*.62; }
function timeToBeat(map,t){ if(t<=map[0].t) return map[0].b+(t-map[0].t)/.62; for(let i=1;i<map.length;i++){const a=map[i-1],c=map[i]; if(t<=c.t) return a.b+(t-a.t)/(c.t-a.t)*(c.b-a.b);} return TOTAL; }

// ---------- piano synth ----------
let ac, master, verb;
function initAudio(){
  ac=new (window.AudioContext||window.webkitAudioContext)();
  const comp=ac.createDynamicsCompressor(); comp.threshold.value=-14; comp.ratio.value=3;
  master=ac.createGain(); master.gain.value=.8; master.connect(comp); comp.connect(ac.destination);
  const conv=ac.createConvolver(), len=ac.sampleRate*1.8, ir=ac.createBuffer(2,len,ac.sampleRate);
  for(let ch=0;ch<2;ch++){const d=ir.getChannelData(ch);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/len,3.2)}
  conv.buffer=ir; verb=ac.createGain(); verb.gain.value=.22; verb.connect(conv); conv.connect(comp);
}
const voices=new Set();
function playNote(m,when,off,vel){
  const f=440*Math.pow(2,(m-69)/12);
  const out=ac.createGain(); out.gain.value=0;
  const lp=ac.createBiquadFilter(); lp.type='lowpass'; lp.Q.value=.4;
  const bright=1200+vel*4200;
  lp.frequency.setValueAtTime(bright,when); lp.frequency.exponentialRampToValueAtTime(Math.max(500,f*3),when+1.2);
  out.connect(lp); lp.connect(master); lp.connect(verb);
  const decay=Math.max(.9,3.6-(m-48)*.06);
  const peak=.16*vel*vel+.04*vel;
  out.gain.setValueAtTime(0,when);
  out.gain.linearRampToValueAtTime(peak,when+.004);
  out.gain.setTargetAtTime(peak*.35,when+.004,.12);
  out.gain.setTargetAtTime(peak*.0001,when+.25,decay/2.2);
  out.gain.setTargetAtTime(0,Math.max(off,when+.06),.07);
  const parts=[[1,1],[2,.42],[3,.22],[4,.12],[5,.07],[6,.04]];
  const nodes=[];
  parts.forEach(([h,a],i)=>{const o=ac.createOscillator(), g=ac.createGain();
    o.type= i===0?'triangle':'sine'; o.frequency.value=f*h*(1+.0004*h*h); o.detune.value=(Math.random()-.5)*3;
    g.gain.value=a; g.gain.setTargetAtTime(a*.2,when,.25/h+.15);
    o.connect(g); g.connect(out); o.start(when); o.stop(Math.max(off,when+.06)+.6); nodes.push(o);});
  // felt hammer thump
  const nb=ac.createBuffer(1,ac.sampleRate*.03,ac.sampleRate), nd=nb.getChannelData(0);
  for(let i=0;i<nd.length;i++) nd[i]=(Math.random()*2-1)*(1-i/nd.length);
  const ns=ac.createBufferSource(); ns.buffer=nb; const bp=ac.createBiquadFilter(); bp.type='bandpass'; bp.frequency.value=f*4+800; bp.Q.value=.8;
  const ng=ac.createGain(); ng.gain.value=.05*vel; ns.connect(bp); bp.connect(ng); ng.connect(master); ns.start(when);
  nodes.push(ns);
  const v={nodes,out}; voices.add(v); nodes[0].onended=()=>voices.delete(v);
}
function silenceAll(){ voices.forEach(v=>{try{v.out.gain.cancelScheduledValues(0);v.out.gain.setValueAtTime(0,ac.currentTime);v.nodes.forEach(n=>n.stop())}catch(e){}}); voices.clear(); }

// ---------- transport ----------
let t0=0, nextIdx=0, playing=false, started=false, seed=7;
perf=makePerformance(seed);
const now=()=> ac ? ac.currentTime - t0 : 0;
function schedule(){
  if(!playing) return;
  const horizon=now()+.2;
  while(nextIdx<perf.events.length && perf.events[nextIdx].on<horizon){
    const e=perf.events[nextIdx++]; if(e.on<now()-.05) continue;
    playNote(midi(e.p),t0+e.on,t0+e.off,e.vel);
  }
}
const _iv=setInterval(schedule,40);
function restart(newSeed){
  if(newSeed){ seed=Math.floor(Math.random()*1e9); perf=makePerformance(seed); }
  silenceAll(); nextIdx=0; t0=ac.currentTime+.05;
  if(!playing){ ac.resume(); playing=true; ppBtn.textContent='Pause'; }
}
const startBtn=root.querySelector('#lp-start'), ppBtn=root.querySelector('#lp-pp');
startBtn.onclick=()=>{ if(!ac) initAudio(); started=true; startBtn.hidden=true; playing=true; ac.resume(); restart(false); };
ppBtn.onclick=()=>{ if(!started){startBtn.click();return}
  if(now()>perf.end){ restart(false); return; }
  if(playing){ ac.suspend(); playing=false; ppBtn.textContent='Play'; } else { ac.resume(); playing=true; ppBtn.textContent='Pause'; } };
root.querySelector('#lp-restart').onclick=()=>{ if(!started){startBtn.click();return} restart(false); };
root.querySelector('#lp-take').onclick=()=>{ if(!started){ seed=Math.floor(Math.random()*1e9); perf=makePerformance(seed); startBtn.click(); return;} restart(true); };

// ---------- drawing ----------
const CLEF_T=new Image(); CLEF_T.src='data:image/png;base64,';
const CLEF_B=new Image(); CLEF_B.src='data:image/png;base64,';
const cv=root.querySelector('#lp-cv'), ctx=cv.getContext('2d');
const W=1200,H=840;
function resize(){const r=cv.getBoundingClientRect(), d=window.devicePixelRatio||1; cv.width=Math.round(r.width*d); cv.height=Math.round(r.height*d);}
const _ro=new ResizeObserver(resize); _ro.observe(cv); resize();

const L=96, R=1104, SP=16;
const TREB_BOT=204, BASS_BOT=364;
const PLAY_X=250, PPB=62, CLIP_X=222;
const yT=n=>TREB_BOT-(dia(n)-30)*SP/2;
const yB=n=>BASS_BOT-(dia(n)-18)*SP/2;
const KB_TOP=470, KB_BOT=700, WK=(R-L)/21, BK_H=140, BK_W=WK*.62;
const KEYS=[]; // C3..B5
for(let o=3;o<=5;o++)['C','D','E','F','G','A','B'].forEach((n,i)=>KEYS.push({n:n+o,x:L+((o-3)*7+i)*WK,white:true}));
const blackAfter={C:1,D:1,F:1,G:1,A:1};
const BLACK=[]; KEYS.forEach(k=>{if(blackAfter[k.n[0]])BLACK.push({x:k.x+WK-BK_W/2})});

function staff(top){ctx.strokeStyle='#15181a';ctx.lineWidth=1.6;for(let i=0;i<5;i++){ctx.beginPath();ctx.moveTo(L,top+i*SP);ctx.lineTo(R,top+i*SP);ctx.stroke();}}
function head(x,y,filled,whole){ctx.save();ctx.translate(x,y);ctx.rotate(whole?-.1:-.38);ctx.beginPath();ctx.ellipse(0,0,whole?11:9.6,whole?7.4:6.6,0,0,Math.PI*2);
  if(filled)ctx.fill();else{ctx.lineWidth=whole?3.2:2.4;ctx.stroke();} ctx.restore();}
function ledgers(x,y,top,bot){ctx.lineWidth=1.6;for(let ly=bot+SP;ly<=y+.1;ly+=SP){ctx.beginPath();ctx.moveTo(x-16,ly);ctx.lineTo(x+16,ly);ctx.stroke();}
  for(let ly=top-SP;ly>=y-.1;ly-=SP){ctx.beginPath();ctx.moveTo(x-16,ly);ctx.lineTo(x+16,ly);ctx.stroke();}}

function draw(){
  const s=cv.width/W; ctx.setTransform(s,0,0,s,0,0);
  const t=now(); const curB=started?timeToBeat(perf.map,t):-3;
  ctx.fillStyle='#fff'; ctx.fillRect(0,0,W,H);
  staff(TREB_BOT-4*SP); staff(BASS_BOT-4*SP);
  const bx=bb=>PLAY_X+(bb-curB)*PPB+22;

  // scrolling music, clipped behind the clefs
  ctx.save(); ctx.beginPath(); ctx.rect(CLIP_X,0,R-CLIP_X+2,440); ctx.clip();
  // bar lines
  ctx.strokeStyle='#15181a'; ctx.lineWidth=1.6;
  bars.forEach((bb,i)=>{const x=bx(bb)-26; if(x<CLIP_X-10||x>R+10||i===0)return;
    const fin=i===bars.length-1;
    [[TREB_BOT-4*SP,TREB_BOT],[BASS_BOT-4*SP,BASS_BOT]].forEach(([a,c])=>{
      ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(x,a);ctx.lineTo(x,c);ctx.stroke();
      if(fin){ctx.lineWidth=6;ctx.beginPath();ctx.moveTo(x+8,a);ctx.lineTo(x+8,c);ctx.stroke();}});});
  // right hand
  rh.forEach(n=>{
    const x=bx(n.b); if(x<CLIP_X-30||x>R+40) return;
    const y=yT(n.p); const done=started&&n.t!==undefined&&t>=n.t-.01;
    const col=done?'#14c8dc':'#15181a'; ctx.fillStyle=col; ctx.strokeStyle='#15181a';
    ledgers(x,y,TREB_BOT-4*SP,TREB_BOT);
    ctx.strokeStyle=col; ctx.fillStyle=col;
    head(x,y,n.d<2,false);
    if(n.d%1!==0&&n.d>1){ctx.beginPath();ctx.arc(x+17,y-(Math.round((y-TREB_BOT)/(SP/2))%2===0?SP/2:0),2.8,0,7);ctx.fill();}
    const sx=x+8.6; ctx.lineWidth=2; ctx.beginPath(); ctx.moveTo(sx,y-2); ctx.lineTo(sx,y-54); ctx.stroke();
    if(n.flag){ctx.lineWidth=2.4;ctx.beginPath();ctx.moveTo(sx,y-54);ctx.bezierCurveTo(sx+4,y-40,sx+18,y-36,sx+12,y-20);ctx.stroke();}
    if(n.beamTo){const x2=bx(n.beamTo.b)+8.6, y2=yT(n.beamTo.p);ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(sx-1,y-54);ctx.lineTo(x2+1,y2-54);ctx.stroke();}
    if(n.f){ctx.fillStyle='#15181a';ctx.font='600 17px Nunito, sans-serif';ctx.textAlign='center';ctx.fillText(n.f,x,Math.min(y-64,TREB_BOT-4*SP-12));}
  });
  // left hand whole/half-note dyads with fingering under
  lh.forEach(c=>{
    const x=bx(c.b); if(x<CLIP_X-30||x>R+40) return;
    const done=started&&c.t!==undefined&&t>=c.t-.01; const col=done?'#14c8dc':'#15181a';
    ctx.strokeStyle=col; ctx.fillStyle=col;
    const ys=c.ps.map(yB);
    c.ps.forEach((p,k)=>head(x,ys[k],false,c.d===4));
    if(c.d===2){ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x-9,Math.min(...ys)+2);ctx.lineTo(x-9,Math.max(...ys)+50);ctx.stroke();}
    ctx.fillStyle='#15181a';ctx.font='600 15px Nunito, sans-serif';ctx.textAlign='center';
    c.ps.slice().reverse().forEach((p,k)=>ctx.fillText(LH_FING[p],x,BASS_BOT+30+k*17));
  });
  ctx.restore();

  // clefs + soft fade where notes slide under them
  const g=ctx.createLinearGradient(CLIP_X,0,CLIP_X+34,0); g.addColorStop(0,'#fff');g.addColorStop(1,'rgba(255,255,255,0)');
  ctx.fillStyle=g; ctx.fillRect(CLIP_X,TREB_BOT-4*SP-80,34,BASS_BOT-TREB_BOT+4*SP+140);
  ctx.fillStyle='#15181a'; ctx.textAlign='left';
  if(CLEF_T.complete) ctx.drawImage(CLEF_T,100,60,80,220);
  if(CLEF_B.complete) ctx.drawImage(CLEF_B,100,230,80,150);
  // time signature
  ctx.font='700 30px Georgia, "Times New Roman", serif'; ctx.textAlign='center';
  [TREB_BOT,BASS_BOT].forEach(bt=>{ctx.fillText('4',L+90,bt-2*SP-3);ctx.fillText('4',L+90,bt+0-3);});

  // glowing playhead
  const px=PLAY_X+22;
  const gl=ctx.createLinearGradient(px-26,0,px+26,0);
  gl.addColorStop(0,'rgba(20,200,220,0)');gl.addColorStop(.5,'rgba(20,200,220,.35)');gl.addColorStop(1,'rgba(20,200,220,0)');
  ctx.fillStyle=gl; ctx.fillRect(px-26,TREB_BOT-4*SP-28,52,BASS_BOT-TREB_BOT+4*SP+56);
  ctx.fillStyle='#14c8dc'; ctx.fillRect(px-2,TREB_BOT-4*SP-28,4,BASS_BOT-TREB_BOT+4*SP+56);

  // keyboard
  const down={};
  if(started) perf.events.forEach(e=>{ if(t>=e.on&&t<e.off+.02){ down[e.p]=e.wrong?'oops':e.type; } });
  KEYS.forEach(k=>{const st=down[k.n];
    ctx.fillStyle= st==='rh'?'#b98cf5': st==='lh'?'#7fd8cc': st==='oops'?'#f58a82':'#fff';
    ctx.fillRect(k.x,KB_TOP,WK,KB_BOT-KB_TOP);
    ctx.strokeStyle='#15181a';ctx.lineWidth=1.6;ctx.strokeRect(k.x,KB_TOP,WK,KB_BOT-KB_TOP);
    if(st){ctx.fillStyle='#fff';ctx.font='700 18px Fredoka, Nunito, sans-serif';ctx.textAlign='center';ctx.fillText(k.n[0],k.x+WK/2,KB_BOT-16);}
    if(k.n==='C4'&&!st){ctx.fillStyle='#9aa6aa';ctx.beginPath();ctx.arc(k.x+WK/2,KB_BOT-22,4,0,7);ctx.fill();}
  });
  ctx.fillStyle='#15181a'; BLACK.forEach(bk=>{ctx.fillRect(bk.x,KB_TOP,BK_W,BK_H)});
  ctx.lineWidth=3; ctx.strokeRect(L,KB_TOP,R-L,KB_BOT-KB_TOP);

  // caption
  ctx.fillStyle='#5b6a70'; ctx.font='700 17px Fredoka, Nunito, sans-serif'; ctx.textAlign='center';
  const fin=started&&t>perf.end-.6;
  ctx.fillText(fin?'Bravo! 👏':'Jingle Bells · J. Pierpont · easy piano',W/2,770);
  if(fin&&playing){ppBtn.textContent='Play again';}
  if(alive) requestAnimationFrame(draw);
}
requestAnimationFrame(draw);

  return {
    get time() { return now(); },
    get end() { return perf.end; },
    get playing() { return playing; },
    get started() { return started; },
    play() { if (!started) { startBtn.click(); return; } if (now() > perf.end) { restart(false); return; } if (!playing) ppBtn.click(); },
    pause() { if (started && playing) ppBtn.click(); },
    destroy() { alive = false; clearInterval(_iv); _ro.disconnect(); try { silenceAll(); ac && ac.close(); } catch (e) {} },
  };
}
